/**
 * Seeded property tests for the allowlisted rich-text renderer
 * (`renderRichText`) and the plain-text projection.
 *
 * Documents are generated by a small deterministic PRNG (mulberry32): every
 * block type, with text biased toward markup metacharacters and entity
 * fragments, and CTA/embed URLs assembled from obfuscated script schemes
 * (mixed case, embedded tab/newline, leading controls and Unicode spaces,
 * encoded colons). The properties: the output contains only allowlisted tags
 * and attributes, every `href`/`src` resolves (as a browser would parse it)
 * to a scheme outside the script/data/file set, and an off-contract document
 * throws the value-free `RichTextRenderError`, never a raw error.
 */

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { richTextSchema, type RichTextBlock, type RichTextDocument } from 'jsails/rich-text';

import {
  RichTextRenderError,
  renderRichText,
  richTextToPlainText,
  type RenderRichTextOptions,
} from '../../src/server/index.js';

// ---------------------------------------------------------------------------
// Seeded generator
// ---------------------------------------------------------------------------

const BASE_SEED = 0x7e47_2001;
const RUNS = 400;

/** mulberry32: a tiny, well-distributed 32-bit PRNG; same seed, same sequence. */
function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Gen {
  chance(p: number): boolean;
  int(min: number, max: number): number;
  pick<T>(items: readonly T[]): T;
  text(maxParts?: number): string;
}

const FRAGMENTS: readonly string[] = [
  '<',
  '>',
  '&',
  '"',
  "'",
  '`',
  '=',
  '/',
  ' ',
  '\t',
  '\n',
  ' ',
  ' ',
  '‮',
  '\ud800',
  '😀',
  'a',
  'Z',
  '&amp;',
  '&#60;',
  '&lt;',
  '<script>alert(1)</script>',
  '<img src=x onerror=alert(1)>',
  '" onmouseover="x',
  "' autofocus onfocus='x",
  '</p>',
  '<!--',
  ']]>',
  'javascript:alert(1)',
  '<a href="javascript:x">',
];

function generator(seed: number): Gen {
  const next = mulberry32(seed);
  const gen: Gen = {
    chance: (p) => next() < p,
    int: (min, max) => min + Math.floor(next() * (max - min + 1)),
    pick: (items) => items[Math.floor(next() * items.length)]!,
    text: (maxParts = 10) => {
      let out = '';
      for (let i = gen.int(0, maxParts); i > 0; i -= 1) out += gen.pick(FRAGMENTS);
      return out;
    },
  };
  return gen;
}

/** Run `check` against `RUNS` seeded cases, naming the failing seed. */
function forAll(check: (gen: Gen) => void): void {
  for (let run = 0; run < RUNS; run += 1) {
    const caseSeed = (BASE_SEED + run) >>> 0;
    try {
      check(generator(caseSeed));
    } catch (error) {
      assert.fail(`property failed for seed ${caseSeed}: ${(error as Error).message}`);
    }
  }
}

// ---------------------------------------------------------------------------
// Hostile URLs
// ---------------------------------------------------------------------------

const URL_PREFIXES = ['', '', ' ', '\t', '\n', '\u0000', '\u000b', '\u001f', ' ', '　', '﻿'];
const URL_SCHEMES = [
  'javascript',
  'JaVaScRiPt',
  'java\tscript',
  'java\nscript',
  'java\rscript',
  'vbscript',
  'data',
  'DATA',
  'file',
  'https',
  'http',
  'mailto',
  'tel',
  'blob',
  'jav&#x61;script',
  'javascript\u0000',
  ' javascript',
  'javascript ',
];
const URL_SEPARATORS = [':', ':', ':', '%3a', '&colon;', '&#58;', '&#x3a;', '\t:'];
const URL_RESTS = [
  'alert(1)',
  '//evil.example/x',
  '//app.example/ok',
  'text/html,<script>alert(1)</script>',
  'text/html;base64,PHNjcmlwdD4=',
  '/etc/passwd',
  'a@b.example',
  '',
];
const PATHS = [
  '/pricing',
  'docs/start',
  '//evil.example',
  '\\\\evil.example',
  '/a?b=<c>',
  '#top',
  '?q="x"',
];

function hostileHref(gen: Gen): string {
  if (gen.chance(0.25)) return gen.pick(URL_PREFIXES) + gen.pick(PATHS);
  return (
    gen.pick(URL_PREFIXES) + gen.pick(URL_SCHEMES) + gen.pick(URL_SEPARATORS) + gen.pick(URL_RESTS)
  );
}

const EMBED_HOSTS = [
  'www.youtube.com',
  'youtube.com',
  'evil.example',
  'youtube.com.evil.example',
  'player.vimeo.com',
];

function embedUrl(gen: Gen): string {
  const scheme = gen.pick(['https', 'http', 'javascript', 'data', 'HTTPS', 'ftp']);
  const credentials = gen.chance(0.2) ? 'user:pass@' : '';
  const tail = gen.pick(['v1', '%3Cscript%3E', '"x"', "'", '<b>', ' a', '?a=1&b=<2>', '#"frag']);
  return `${scheme}://${credentials}${gen.pick(EMBED_HOSTS)}/embed/${tail}`;
}

// ---------------------------------------------------------------------------
// Documents
// ---------------------------------------------------------------------------

function block(gen: Gen, index: number): RichTextBlock {
  const id = `b${index}`;
  switch (gen.int(0, 10)) {
    case 0:
      return { id, type: 'paragraph', text: gen.text() };
    case 1:
      return { id, type: 'heading', level: gen.pick([2, 3, 4, 5, 6] as const), text: gen.text() };
    case 2:
      return {
        id,
        type: 'list',
        style: gen.pick(['ordered', 'unordered'] as const),
        items: Array.from({ length: gen.int(0, 4) }, () => gen.text(4)),
      };
    case 3:
      return {
        id,
        type: 'quote',
        text: gen.text(),
        ...(gen.chance(0.5) ? { citation: gen.text(4) } : {}),
      };
    case 4:
      return {
        id,
        type: 'code',
        code: gen.text(),
        ...(gen.chance(0.5) ? { language: gen.text(2) } : {}),
      };
    case 5:
      return {
        id,
        type: 'image',
        mediaId: gen.pick(['known', 'missing', gen.text(2) || 'x']),
        ...(gen.chance(0.5) ? { alt: gen.text(3) } : {}),
        ...(gen.chance(0.5) ? { caption: gen.text(3) } : {}),
      };
    case 6:
      return {
        id,
        type: 'gallery',
        mediaIds: Array.from({ length: gen.int(0, 3) }, () => gen.pick(['known', 'missing'])),
        ...(gen.chance(0.5) ? { alt: gen.text(3) } : {}),
      };
    case 7:
      return { id, type: 'embed', url: embedUrl(gen) };
    case 8:
      return {
        id,
        type: 'callout',
        tone: gen.pick(['info', 'success', 'warning', 'danger'] as const),
        text: gen.text(),
      };
    case 9:
      return { id, type: 'cta', label: gen.text(3) || 'Go', href: hostileHref(gen) || '/' };
    default:
      return { id, type: 'divider' };
  }
}

function documentOf(gen: Gen): RichTextDocument {
  return { version: 1, blocks: Array.from({ length: gen.int(1, 8) }, (_, i) => block(gen, i)) };
}

const OPTIONS: RenderRichTextOptions = {
  resolveMedia: (mediaId) =>
    mediaId === 'known'
      ? { src: '/media/known.png', alt: 'fallback "alt"', width: 10, height: 10 }
      : undefined,
  embedHostAllowlist: ['.youtube.com', 'player.vimeo.com'],
};

// ---------------------------------------------------------------------------
// Output checks
// ---------------------------------------------------------------------------

const ALLOWED_TAGS = new Set([
  'p',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'ul',
  'ol',
  'li',
  'blockquote',
  'footer',
  'cite',
  'pre',
  'code',
  'img',
  'figure',
  'figcaption',
  'div',
  'iframe',
  'aside',
  'a',
  'span',
  'hr',
]);
const ALLOWED_ATTRIBUTES = new Set([
  'class',
  'src',
  'alt',
  'width',
  'height',
  'loading',
  'href',
  'rel',
  'allowfullscreen',
  'aria-hidden',
]);
const FORBIDDEN_PROTOCOLS = new Set(['javascript:', 'vbscript:', 'data:', 'file:']);
const TAG_RE = /<(\/?)([a-z][a-z0-9]*)((?:\s+[a-z-]+(?:="[^"<>]*")?)*)\s*>/g;
const ATTRIBUTE_RE = /\s+([a-z-]+)(?:="([^"]*)")?/g;

const NAMED_REFERENCES: Readonly<Record<string, string>> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
};

/**
 * Decode an attribute value the way a browser does before the URL parser sees
 * it. Numeric references are decoded in full; a named reference outside the
 * escaper's set, or a bare `&`, fails the property instead of being read
 * literally, since a browser could resolve it to a scheme character.
 */
function decodeAttribute(value: string): string {
  return value.replace(/&(#[xX][0-9a-fA-F]+|#[0-9]+|[A-Za-z][A-Za-z0-9]*)?;?/g, (match, body) => {
    const reference = body as string | undefined;
    if (reference?.startsWith('#') === true) {
      const hex = reference[1] === 'x' || reference[1] === 'X';
      const codePoint = hex ? parseInt(reference.slice(2), 16) : Number(reference.slice(1));
      return codePoint > 0 && codePoint <= 0x10ffff ? String.fromCodePoint(codePoint) : '\ufffd';
    }
    const named = reference === undefined ? undefined : NAMED_REFERENCES[reference];
    assert.ok(named !== undefined && match.endsWith(';'), `unexpected reference ${match}`);
    return named;
  });
}

/** Assert the fragment is built only from allowlisted tags, attributes, and URL schemes. */
function assertAllowlisted(html: string): void {
  for (const match of html.matchAll(TAG_RE)) {
    const [, , tag, attributes] = match;
    assert.ok(ALLOWED_TAGS.has(tag!), `tag <${tag}> is outside the allowlist`);
    for (const [, name, value] of attributes!.matchAll(ATTRIBUTE_RE)) {
      assert.ok(ALLOWED_ATTRIBUTES.has(name!), `attribute ${name} is outside the allowlist`);
      if ((name === 'href' || name === 'src') && value !== undefined) {
        // The WHATWG parser is the browser's: it strips leading C0/space and
        // embedded tab/newline before reading the scheme.
        // An unparseable URL is not navigable at all.
        const parsed = URL.parse(decodeAttribute(value), 'https://app.example/base/');
        if (parsed !== null) {
          assert.ok(
            !FORBIDDEN_PROTOCOLS.has(parsed.protocol),
            `${name} resolves to ${parsed.protocol}`,
          );
        }
      }
    }
  }
  const residue = html.replace(TAG_RE, '');
  assert.doesNotMatch(residue, /[<>]/, 'markup outside a recognized tag');
}

describe('property: renderRichText allowlist', () => {
  it('emits only allowlisted tags, attributes, and URL schemes', () => {
    let rendered = 0;
    forAll((gen) => {
      const doc = documentOf(gen);
      if (!richTextSchema.safeParse(doc).success) return;
      assertAllowlisted(renderRichText(doc, OPTIONS));
      rendered += 1;
    });
    // Guard against a generator that drifts off-contract and tests nothing.
    assert.ok(rendered > RUNS / 2, `only ${rendered} generated documents were valid`);
  });

  it('renders every CTA with a script-free href or as an unlinked label', () => {
    forAll((gen) => {
      const href = hostileHref(gen) || '/';
      const html = renderRichText({
        version: 1,
        blocks: [{ id: 'c', type: 'cta', label: 'Go', href }],
      });
      assertAllowlisted(html);
      const linked = /<a href="([^"]*)"/.exec(html);
      if (linked !== null) {
        assert.equal(decodeAttribute(linked[1]!), href, 'a linked href is the authored value');
      }
    });
  });

  it('only frames https embeds on an allowlisted host', () => {
    let framedCount = 0;
    let unframedCount = 0;
    forAll((gen) => {
      const url = embedUrl(gen);
      const doc: RichTextDocument = { version: 1, blocks: [{ id: 'e', type: 'embed', url }] };
      if (!richTextSchema.safeParse(doc).success) return;
      const html = renderRichText(doc, OPTIONS);
      const framed = /<iframe src="([^"]*)"/.exec(html);
      if (framed === null) {
        unframedCount += 1;
        return;
      }
      framedCount += 1;
      const src = new URL(decodeAttribute(framed[1]!));
      assert.equal(src.protocol, 'https:');
      assert.ok(
        src.hostname === 'player.vimeo.com' || /(^|\.)youtube\.com$/.test(src.hostname),
        src.hostname,
      );
    });
    // Both outcomes must occur, or the generator has drifted and the property is vacuous.
    assert.ok(framedCount > 0, 'no embed was ever framed');
    assert.ok(unframedCount > 0, 'no embed was ever refused');
  });

  it('throws only RichTextRenderError for an off-contract document', () => {
    forAll((gen) => {
      const doc = documentOf(gen) as unknown as { blocks: Record<string, unknown>[] };
      const target = doc.blocks[gen.int(0, doc.blocks.length - 1)]!;
      const mutation = gen.int(0, 4);
      if (mutation === 0) target.type = gen.pick(['html', 'script', 'raw', '__proto__']);
      else if (mutation === 1) target.html = '<script>alert(1)</script>';
      else if (mutation === 2) target.id = '';
      else if (mutation === 3) target.text = 42;
      else (doc as unknown as { version: unknown }).version = gen.pick([0, 2, '1', null]);
      if (richTextSchema.safeParse(doc).success) return;
      assert.throws(
        () => renderRichText(doc as unknown as RichTextDocument, OPTIONS),
        (error: unknown) => {
          assert.ok(error instanceof RichTextRenderError, String(error));
          assert.doesNotMatch(error.message, /<script>/);
          return true;
        },
      );
    });
  });
});

describe('property: richTextToPlainText', () => {
  it('never throws on a valid document and returns a string', () => {
    forAll((gen) => {
      const doc = documentOf(gen);
      if (!richTextSchema.safeParse(doc).success) return;
      assert.equal(typeof richTextToPlainText(doc), 'string');
    });
  });
});
